window.DV_TOPICS=window.DV_TOPICS||{};window.DV_TOPICS["electricity-bill"]={"id":"electricity-bill","order":18,"title_en":"Electricity Bill","title_zh":"电费账单","blurb_zh":"十月到十一月，电费为什么涨了","scene_zh":"一个三口之家的月度电费与用电记录（模拟数据）","views":[{"id":"bill","type":"waterfall","label_zh":"账单变化","label_en":"Bill change","subject":"Monthly electricity bill","subtitle_en":"What moved the electricity bill from October to November.","unit":{"en":"yuan","short":"¥","decimals":0,"kind":"count"},"data":{"start":{"name_en":"October"},"end":{"name_en":"November"},"start_value":320,"steps":[{"id":"heating","name_en":"Heating","name_zh":"供暖","value":95},{"id":"ac_off","name_en":"AC off","name_zh":"停用空调","value":-60},{"id":"lighting","name_en":"Lighting","name_zh":"照明","value":22},{"id":"new_fridge","name_en":"New fridge","name_zh":"新冰箱","value":-18},{"id":"tier_surcharge","name_en":"Tier surcharge","name_zh":"阶梯加价","value":35},{"id":"shorter_showers","name_en":"Shorter showers","name_zh":"缩短洗澡","value":-14}]},"features":[{"kind":"largest_step","marks":["step:heating"],"slots":{"subject":"Monthly electricity bill","category":"Heating","value":"95 yuan","signed":"+95 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":false,"id":"eb-heating","examples":[{"en":"Heating added 95 yuan to the bill, the largest single step from October to November.","zh":"供暖让账单增加了 95 元，是十月到十一月最大的一笔变化。"}],"note_zh":"largest single step 强调单项最大，不要说 the most step。","interpret_zh":"供暖是增项，但如果没有停用空调省下的 60 元，净增幅会更大。"},{"kind":"decrease_contributor","marks":["step:ac_off"],"slots":{"subject":"Monthly electricity bill","category":"AC off","value":"60 yuan","signed":"-60 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":false,"id":"eb-ac","examples":[{"en":"Turning off the air conditioning took 60 yuan off the bill.","zh":"停用空调让账单少了 60 元。"}],"note_zh":"take ... off 是口语里最直接的减法表达。","interpret_zh":"这一项是主动节约，和季节带来的被动变化不同。"},{"kind":"increase_contributor","marks":["step:lighting"],"slots":{"subject":"Monthly electricity bill","category":"Lighting","value":"22 yuan","signed":"+22 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":true},{"kind":"decrease_contributor","marks":["step:new_fridge"],"slots":{"subject":"Monthly electricity bill","category":"New fridge","value":"18 yuan","signed":"-18 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":false,"id":"eb-fridge","examples":[{"en":"The new fridge cut 18 yuan from the bill.","zh":"新冰箱让账单省下 18 元。"}],"note_zh":"cut + 数值 + from 表示削减。","interpret_zh":"换家电的节省是一个月的数据，全年累计会更大。"},{"kind":"increase_contributor","marks":["step:tier_surcharge"],"slots":{"subject":"Monthly electricity bill","category":"Tier surcharge","value":"35 yuan","signed":"+35 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":false,"id":"eb-tier","examples":[{"en":"The tier surcharge pushed the bill up by another 35 yuan.","zh":"阶梯电价又推高了 35 元。"}],"note_zh":"push up by + 数值 说推动的幅度。","interpret_zh":"阶梯加价由总用电量触发，不单纯是单价上涨。"},{"kind":"decrease_contributor","marks":["step:shorter_showers"],"slots":{"subject":"Monthly electricity bill","category":"Shorter showers","value":"14 yuan","signed":"-14 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":false,"id":"eb-showers","examples":[{"en":"Shorter showers saved 14 yuan, the smallest saving of the month.","zh":"缩短洗澡时间省下 14 元，是当月最小的一笔节省。"}],"note_zh":"saving 作名词说节省额；smallest 修饰 saving。","interpret_zh":"单项金额小，但这是可以长期保持的习惯改动。"},{"kind":"net_change","marks":["total:start","total:end"],"slots":{"subject":"Monthly electricity bill","category":"October","value":"320 yuan","start":"320 yuan","end":"380 yuan","pct":"19","pp":"60","period":"","unit":"¥"},"auto":false,"id":"eb-net","examples":[{"en":"The bill went from 320 to 380 yuan, a net change of 60 yuan.","zh":"账单从 320 元变到 380 元，净变化 60 元。"}],"note_zh":"net change 是正负相抵后的结果，不指向某一项。","interpret_zh":"净增 60 元约合 19%，只看净额会忽略六项的来回抵消。"}],"overview_zh":"十一月账单比十月高 60 元：供暖和阶梯加价推高，停用空调、换冰箱和缩短洗澡时间各拉低一部分。净变化不大，内部结构变化却很剧烈。","descriptions":{"general":{"a2":"The electricity bill went up from 320 yuan in October to 380 yuan in November. Heating added the most, 95 yuan. Turning off the air conditioning saved 60 yuan.","b1":"The bill rose from 320 to 380 yuan, a net increase of 60 yuan. Heating was the largest single step at 95 yuan, while the tier surcharge added 35 yuan. Savings from turning off the AC, buying a new fridge and taking shorter showers offset part of the rise.","b2":"November's bill came in at 380 yuan, up 60 yuan from October's 320. Heating drove the change with a 95-yuan addition, followed by a 35-yuan tier surcharge. Three reductions, namely no air conditioning, a more efficient fridge and shorter showers, removed 92 yuan in total and softened the net rise."},"ielts":"The monthly electricity bill rose from 320 yuan in October to 380 yuan in November. Heating contributed an additional 95 yuan, while a tier surcharge added 35 yuan. These increases were partly offset by savings of 60 yuan from turning off the air conditioning.","business":"The bill is up 60 yuan month over month, driven by heating and the tier surcharge. Usage-side savings from the AC, the new fridge and shorter showers recovered 92 yuan. The lesson is that price-tier exposure, not usage alone, now drives the winter bill."}},{"id":"usage","type":"line","label_zh":"按月用电","label_en":"Monthly usage","subject":"Household electricity use","subtitle_en":"Monthly electricity use for the same household.","unit":{"en":"kWh","short":"kWh","decimals":0,"kind":"count"},"data":{"x":{"label_en":"Month","label_zh":"月份","values":["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]},"series":[{"id":"usage","name_en":"Electricity use","name_zh":"用电量","slot":1,"values":[410,380,330,290,270,310,390,430,360,300,340,420]}]},"features":[{"kind":"fall_slight","marks":["seg:usage:0"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Jan to Feb","series_name":"Electricity use","from":"410 kWh","to":"380 kWh","from_period":"Jan","to_period":"Feb","pct":"7.3","pp":"30","delta":"30 kWh"},"auto":true},{"kind":"fall_steady","marks":["seg:usage:1"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Feb to Mar","series_name":"Electricity use","from":"380 kWh","to":"330 kWh","from_period":"Feb","to_period":"Mar","pct":"13","pp":"50","delta":"50 kWh"},"auto":true},{"kind":"fall_steady","marks":["seg:usage:2"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Mar to Apr","series_name":"Electricity use","from":"330 kWh","to":"290 kWh","from_period":"Mar","to_period":"Apr","pct":"12","pp":"40","delta":"40 kWh"},"auto":true},{"kind":"fall_slight","marks":["seg:usage:3"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Apr to May","series_name":"Electricity use","from":"290 kWh","to":"270 kWh","from_period":"Apr","to_period":"May","pct":"6.9","pp":"20","delta":"20 kWh"},"auto":true},{"kind":"rise_steady","marks":["seg:usage:4"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"May to Jun","series_name":"Electricity use","from":"270 kWh","to":"310 kWh","from_period":"May","to_period":"Jun","pct":"15","pp":"40","delta":"40 kWh"},"auto":true},{"kind":"rise_sharp","marks":["seg:usage:5"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Jun to Jul","series_name":"Electricity use","from":"310 kWh","to":"390 kWh","from_period":"Jun","to_period":"Jul","pct":"26","pp":"80","delta":"80 kWh"},"auto":false,"id":"el-summer","examples":[{"en":"Usage jumped from 310 kWh in June to 390 kWh in July.","zh":"用电量从六月的 310 千瓦时跳到七月的 390 千瓦时。"}],"note_zh":"jump from ... to ... 暗示一步到位，口语常用。","interpret_zh":"单月增加 80 千瓦时，是全年最快的上升区间。"},{"kind":"rise_steady","marks":["seg:usage:6"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Jul to Aug","series_name":"Electricity use","from":"390 kWh","to":"430 kWh","from_period":"Jul","to_period":"Aug","pct":"10","pp":"40","delta":"40 kWh"},"auto":true},{"kind":"fall_steady","marks":["seg:usage:7"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Aug to Sep","series_name":"Electricity use","from":"430 kWh","to":"360 kWh","from_period":"Aug","to_period":"Sep","pct":"16","pp":"70","delta":"70 kWh"},"auto":false,"id":"el-autumn","examples":[{"en":"Usage fell from 430 kWh in August to 360 kWh in September.","zh":"用电量从八月的 430 千瓦时降到九月的 360 千瓦时。"}],"note_zh":"fall 的过去式是 fell，不要写成 falled。","interpret_zh":"下降 70 千瓦时，但九月仍高于春季水平。"},{"kind":"fall_steady","marks":["seg:usage:8"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Sep to Oct","series_name":"Electricity use","from":"360 kWh","to":"300 kWh","from_period":"Sep","to_period":"Oct","pct":"17","pp":"60","delta":"60 kWh"},"auto":true},{"kind":"rise_steady","marks":["seg:usage:9"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Oct to Nov","series_name":"Electricity use","from":"300 kWh","to":"340 kWh","from_period":"Oct","to_period":"Nov","pct":"13","pp":"40","delta":"40 kWh"},"auto":true},{"kind":"turning_point","marks":["seg:usage:10"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Nov to Dec","series_name":"Electricity use","from":"340 kWh","to":"420 kWh","from_period":"Nov","to_period":"Dec","pct":"24","pp":"80","delta":"80 kWh"},"auto":false,"id":"el-december","examples":[{"en":"Consumption changed direction in December, rising from 340 to 420 kWh.","zh":"用电量在十二月改变方向，从 340 升到 420 千瓦时。"}],"note_zh":"change direction 指方向反转，不说明原因。","interpret_zh":"十二月回升到 420 千瓦时，接近一月水平。"},{"kind":"peak","marks":["pt:usage:0"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Jan","series_name":"Electricity use","value":"410 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":false,"id":"el-january","examples":[{"en":"The year opened with a January peak of 410 kWh.","zh":"年初一月是用电高峰，为 410 千瓦时。"}],"note_zh":"open with 说起点；peak 作名词可数。","interpret_zh":"一月高点是冬季的第二个峰，不是全年最高。"},{"kind":"point","marks":["pt:usage:1"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Feb","series_name":"Electricity use","value":"380 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"point","marks":["pt:usage:2"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Mar","series_name":"Electricity use","value":"330 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"point","marks":["pt:usage:3"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Apr","series_name":"Electricity use","value":"290 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"trough","marks":["pt:usage:4"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"May","series_name":"Electricity use","value":"270 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":false,"id":"el-trough","examples":[{"en":"Usage hit its lowest point in May, at 270 kWh.","zh":"用电量在五月达到最低点，为 270 千瓦时。"}],"note_zh":"hit its lowest point in + 月份；比 bottom 正式。","interpret_zh":"五月低谷处在春季和初夏之间，是一年里最省电的时候。"},{"kind":"point","marks":["pt:usage:5"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Jun","series_name":"Electricity use","value":"310 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"point","marks":["pt:usage:6"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Jul","series_name":"Electricity use","value":"390 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"peak","marks":["pt:usage:7"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Aug","series_name":"Electricity use","value":"430 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":false,"id":"el-peak","examples":[{"en":"August was the highest month, at 430 kWh.","zh":"八月是用电最高的月份，为 430 千瓦时。"}],"note_zh":"peak 作动词可说 peaked at；作名词说 reached its peak。","interpret_zh":"八月峰值与空调使用同步，但图里没有温度数据。"},{"kind":"point","marks":["pt:usage:8"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Sep","series_name":"Electricity use","value":"360 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"trough","marks":["pt:usage:9"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Oct","series_name":"Electricity use","value":"300 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"point","marks":["pt:usage:10"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Nov","series_name":"Electricity use","value":"340 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true},{"kind":"peak","marks":["pt:usage:11"],"slots":{"subject":"Household electricity use","unit":"kWh","category":"","period":"Dec","series_name":"Electricity use","value":"420 kWh","peak":"430 kWh","peak_period":"Aug"},"auto":true}],"overview_zh":"全年用电呈双峰：一月 410 千瓦时和八月 430 千瓦时最高，五月 270 千瓦时最低。春季下降、夏季陡升、秋季回落、年底反弹。","descriptions":{"general":{"a2":"Electricity use was high in January and August and low in May. The hottest and coldest months used the most power. Use fell again in the fall and rose at the end of the year.","b1":"Monthly use ranged from 270 kWh in May to 430 kWh in August. It fell through the spring, climbed sharply in July, and dropped again in the fall before a December rebound.","b2":"Usage followed two clear peaks: 410 kWh in January and 430 kWh in August, with a May trough of 270 kWh. The July jump added 80 kWh in a single month, and the autumn decline was almost as steep before December recovered to 420 kWh."},"ielts":"Electricity use was lowest in May, at 270 kWh, and highest in August, at 430 kWh. Consumption declined through the spring, rose sharply in July, then fell steadily in the autumn before recovering to 420 kWh in December.","business":"Winter heating and summer cooling set the shape of the curve, with peaks in January and August. May is the low season at 270 kWh. Budgeting should weight the two peak windows, not the annual average."}}]};
